import json,pathlib,hashlib,collections
p=pathlib.Path(__file__).resolve().parent
b=json.loads((p.parent/'inputs/baseline.json').read_text()); scope=json.loads((p/'scope.json').read_text()); refs={x['id']:x for x in b['comparison_boards']}
# Each finding below follows pixel inspection of the pinned board and the independent observations.
findings={
'morocco':('hold','Unresolved ceramic interlocking/corner fidelity in explicitly partial v6.','Atlas ornament, banded rose body and tile border survive, but the specifically requested ceramic contrast/interlocking/corner composition and lid-edge grain remain unresolved. This is a named fidelity obligation, not a generic demand for photorealism; the lighter promotional palette alone is not the reason for the hold.'),
'namibia':('accept','Compact ochre dunes and subdued playa versus pale peach promotional terrain.','Raised dunes and pale playa are visibly present. Accept their compact stylized treatment and warmer palette rather than demand promotional sculpting. Dark seam and endpoint hinge ambiguity do not demonstrate detachment; archive hold remains separate.'),
'new-zealand':('accept','Triangular slopes, regular striations and flat turquoise channel.','Twin rocky masses, green slopes, water and slate layered body remain coherent. These finish differences do not erase the terrain motif. Preserve the historical inventory hold and unverified mechanical-contact caveats.'),
'nicaragua':('accept','Smaller fluted volcano relief, saturated green terrain and mottled stone.','Both volcanoes, island and cyan lake survive. Independent observations and pixels support a stylized miniature rather than missing craters or a missing second volcano; exact terrain proportions and stone realism are not claimed.'),
'north-korea':('accept','Simplified white caldera and flat blue lake.','The raised crater encloses visible blue water and retains the slate chest identity. Accept smooth terrain, stronger patterning and reduced lake depth cues as disclosed stylization; unmatched cameras cannot establish dimensional loss.'),
'pacific-ocean':('hold','Broad pale lid field replaced by strongly blue-patterned coverage.','Atoll ring, lagoon and dark peak survive, but the broad pale lid versus blue ocean body material boundary is substantially changed. Preserve the specific pale-lid-coverage fidelity hold; this is a large surface allocation difference, not merely reduced gloss or rocky faceting.'),
'pakistan':('accept','Soft floral repeat, subdued glaze and faceted fittings.','All three pale flowers remain on the cobalt lid above the ivory-blue patterned body. Motif placement and palette are coherent; gray irregular feet also occur in the reference. Accept material and small-detail simplification.'),
'poland':('accept','Low-contrast lid pattern and chalkier ceramic finish.','Original-resolution reinspection resolves the contact-sheet false alarm: faint motifs remain on the cream lid and the central blue flower is present. Accept weaker motif contrast and simplified glaze; no demonstrated missing patterned field.'),
'republic-of-the-congo':('accept','Wood-like brown finish and simplified canopy/shoreline.','Trees around the wetland clearing, green trim and brown chest preserve the theme. Fuller promotional foliage and leather-like shading are ordinary finish differences, not absent forest or water.'),
'rwanda':('accept','Painted-wood-like surface and angular relief instead of rich plaster texture.','Contrasting diamond relief and three framed lid ornaments remain visible. Strong seam and ridging are also reference features. Accept stylized material treatment while preserving the independent exact-byte archive hold.'),
'saint-lucia':('accept','Cloudy stone body and graphic mountain facets.','Both unequal Pitons, green island and turquoise water field remain legible. Pale triangular mountain marks occur in the reference too; photographic vegetation is not a missing requirement.'),
'san-marino':('accept','Bright uniform stone and simplified rock shading.','All three unequal crenellated towers, rocky base, blue seam and main fittings remain. This is low-severity polish, not lost architecture or demonstrated mechanical failure.'),
'sao-tome-and-principe':('hold','Dominant repetitive gray-green checks replace subdued pale-blue stone character.','Needle and rainforest miniature survive, but the body/interior pattern becomes a dominant checker-like treatment rather than the reference pale stone field. Independent review confirms this large pattern mismatch; retain substantive material-identity fidelity hold, without diagnosing renderer malfunction or authorizing redesign.'),
'seychelles':('accept','Subdued granite grain and low-contrast shoreline relief.','Three rounded boulders, turquoise lagoon, pale shoreline and trim remain. Grain is subdued in the reference too. Accept chalky stylization and weak shoreline depth cues rather than declaring missing granite or lagoon.'),
'sierra-leone':('accept','Lobed ornamental canopy, blunt roots and regular bark furrows.','Three trunks/crowns, green ground and scored brown body remain. Reference itself uses ornamental trees and prominent roots; accept a stylized grove, not a photoreal rainforest claim.'),
'singapore':('accept','Applied sculptural flowers and cloudy celadon rather than refined enamel.','Three pink orchid-like ornaments, green foliage, bordered panel and celadon chest remain. Accept relief/material interpretation; visible seams and small fittings are not proven broken by endpoint stills.'),
'slovakia':('accept','Regular wood grain and lighter lid/body tonal split.','White diamonds, visibly raised lid ornaments, timber joinery and hardware remain. The independent correction that lid relief is present is supported by the board; accept tonal and grain simplification.'),
'solomon-islands':('accept','Warmer brown/tan timber and flatter shell-like inlay than charcoal promo.','Pale diamond bands and curved segmented lid motif remain on the dark-grained chest. Accept warm lighting/material interpretation and reduced shell sheen with disclosure; no ornament removal is established.'),
'south-korea':('accept','Dark low-contrast lacquer and angular pale pearl flowers.','Flower layout, framed lid and dark chest match; pointed geometric petals already occur in the reference. Accept reduced iridescence, brass depth and interior readability without claiming exact pearl realism.'),
'spain':('accept','Smooth orange terracotta versus granular coral promotional frame.','Original-resolution reinspection confirms the central flower and pale circular base are visibly raised; the contact-sheet apparent absence was scale-related. Tiles, border and hardware remain; accept palette and finish differences.'),
'switzerland':('accept','Generic snowy pyramid, spiky snow transition and repetitive walnut grain.','Mountain, exposed timber joints, green band and stone feet survive. The reference already uses a simplified pyramidal mountain; accept an Alpine-inspired miniature without claiming precise Matterhorn geography.'),
 'tanzania':('accept','Soft repetitive ochre texture and simplified summit detail.','Green foothills, gray mountain and white recessed summit remain. Accept the painted-miniature rendering and disclose conspicuous repeated interior texture; no missing Kilimanjaro motif is established.'),
 'turkey':('accept','Saturated scarlet tulips, turquoise foliage and soft panel repeats.','Three tulip forms and the blue/ivory patterned chest retain the source composition. Accept graphic ornament and abrupt pattern boundaries; no lost composition or proven hinge failure.'),
 'tuvalu':('accept','Compact faceted sand platform and regular weave.','Turquoise lagoon remains enclosed by pale island rim above woven cream body and coral trim. Accept simplified shore shape and weave rather than equating promotional contour richness with missing geometry.'),
 'united-arab-emirates':('accept','Smooth painted-looking red/ivory finish and chunky brass.','Striped body and lid diamonds remain; dark edge bars and broad seam also occur in the reference. Accept material simplification and awkward but unclipped title wrapping; no missing textile motif.'),
 'uruguay':('accept','Shallow-looking winding channel and repetitive stone mottling.','Raised green banks, winding pale-blue channel and round vegetation remain. Accept a stylized grassland/channel miniature, disclose weak gorge-depth readability, and do not infer measured terrain shallowness from unmatched views.'),
 'uzbekistan':('accept','Washed-out turquoise ornament and subdued medallion relief.','Original board reinspection shows medallion and pale turquoise intervening decoration retained. Accept low contrast and reduced relief legibility; no claim of exact embossed depth or missing decoration. Title wrap is cosmetic.'),
 'vanuatu':('accept','Uniform pale ember patch and coarse ash rather than richly molten texture.','Raised volcano and recessed orange-yellow crater center remain. Accept simplified ember shading within the miniature style, without claiming photoreal lava; no missing volcano or crater.'),
 'vietnam':('accept','Opaque water, green cap-like summits and cloudy limestone body.','Five karst stacks and turquoise water field remain. These graphic caps also occur in the reference; accept simplified material response and do not treat exterior terrain hidden in open views as absent.'),
 'zimbabwe':('accept','Regular masonry and smooth balancing-pebble interpretation.','Stacked stones, adjacent stone, ochre base and pale courses remain. Reference likewise uses smooth stacked rocks; accept the miniature without claiming geographically precise weathered kopjes or artisan authenticity.')
}
assert set(findings)=={e['id'] for e in scope}
out=[]
for e in scope:
 id=e['id']; kind,issue,reason=findings[id]; r=refs[id]
 assert hashlib.sha256((p/'boards'/(id+'.jpg')).read_bytes()).hexdigest()==r['sha256']
 out.append(dict(id=id,disposition='substantive-feature-hold' if kind=='hold' else 'preview-accepted-with-limitations',issue=issue,rationale=reason,evidence={k:r[k] for k in ['commit','path','sha256']}))
(p/'decisions.json').write_text(json.dumps(out,indent=2)+'\n')
counts=collections.Counter(x['disposition'] for x in out)
assert len(out)==len({x['id'] for x in out})==30
print(dict(counts)); print(str(p/'decisions.json'))
